  const businessMonth = date => { const d = new Date(`${String(date||'').slice(0,10)}T00:00:00`); if (Number.isNaN(d.getTime())) return ''; if (d.getDate() < 6) d.setMonth(d.getMonth()-1); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; };
