async function load() {
  if (!from.value || !to.value || from.value > to.value) { error.value = 'Choose a valid date range.'; return; }
  controller?.abort();
  const current = new AbortController(); controller = current;
  loading.value = true; error.value = '';
  try {
    const response = await request('life_stores_360_live_api', { args: { from_date: from.value, to_date: to.value }, signal: current.signal, csrfToken: session.csrf_token });
    const result = response.message;
    if (!result || !Array.isArray(result.items) || !Array.isArray(result.stock_requests) || !Array.isArray(result.purchases)) throw new Error('The stock service returned an incomplete response.');
    if (controller === current) data.value = result;
  } catch (cause) {
    if (controller === current && cause.name !== 'AbortError') error.value = cause.message || 'Could not load stock data.';
  } finally { if (controller === current) loading.value = false; }
}
function setPeriod(days) { to.value=localDate(today); from.value=localDate(new Date(today.getFullYear(),today.getMonth(),today.getDate()-days)); load(); }
function reset() { branch.value = ''; category.value = ''; stockType.value='';vendorFilter.value='';movementStatus.value='';requestState.value='';requestSource.value='';diffFilter.value='';movementType.value='';query.value = ''; from.value = localDate(new Date(today.getFullYear(), today.getMonth(), 1)); to.value = localDate(today); load(); }
function printReport() { window.print(); }
async function openItem(code) {
  selectedItem.value = code; tab.value = 'item'; itemHistory.value = null; detailLoading.value = true;
  detailController?.abort(); const current = new AbortController(); detailController = current;
  try {
    const response = await request('life_stores_360_live_api', { args:{action:'item_history',item_code:code}, signal:current.signal, csrfToken:session.csrf_token });
    if (!response.message?.ok) throw new Error(response.message?.message || 'Item history is unavailable.');
    if (detailController === current) itemHistory.value = response.message;
  } catch (cause) { if (detailController === current && cause.name !== 'AbortError') actionError.value = cause.message; }
  finally { if (detailController === current) detailLoading.value = false; }
}
async function searchFullHistory() {
