  const match=(data.value?.items||[]).find(row=>row.code.toLocaleLowerCase()===term)||(data.value?.items||[]).find(row=>row.code.toLocaleLowerCase().includes(term)||row.name.toLocaleLowerCase().includes(term));
  if(!match){historyError.value='No stock item matches that search.';return;}
  historyLoading.value=true;historyError.value='';itemHistory.value=null;
  try{const response=await request('life_stores_360_live_api',{args:{action:'item_history',item_code:match.code},csrfToken:session.csrf_token});if(!response.message?.ok)throw new Error(response.message?.message||'Item history is unavailable.');itemHistory.value=response.message;selectedItem.value=match.code;}
  catch(cause){historyError.value=cause.message||'Could not load complete item history.';}
  finally{historyLoading.value=false;}
}
function openVendor(code) { selectedVendor.value = code; tab.value = 'vendor'; }
function suppliersForItem(code) { return [...new Set([...(data.value?.item_vendors?.[code]||[]),...(data.value?.purchases||[]).filter(row=>row.item===code).map(row=>row.vendor).filter(Boolean)])]; }
async function searchClients() {
  const term = query.value.trim();
  if (term.length < 2) { clientMatches.value = []; clientLookupError.value = 'Enter a client name, ID, or mobile digits.'; return; }
  clientLookupBusy.value = true; clientLookupError.value = '';
  try {
    const response = await request('life_stores_360_live_api', { args:{action:'client_search',q:term}, csrfToken:session.csrf_token });
    clientMatches.value = response.message?.clients || [];
    if (!clientMatches.value.length) clientLookupError.value = 'No matching client found.';
  } catch (cause) { clientLookupError.value = cause.message || 'Client lookup failed.'; }
  finally { clientLookupBusy.value = false; }
}
function addToOrder(row) {
  const item = itemByCode(row.code || row.item), existing = cart.value.find(entry=>entry.item===item.code);
  if (existing) { existing.qty += Math.max(1,number(stockRows.value.find(stock=>stock.code===item.code)?.suggestedQty)); cartOpen.value=true; return; }
  const supplierCode = suppliersForItem(item.code)[0] || '';
  const stockRow = stockRows.value.find(row=>row.code===item.code);
  cart.value.push({item:item.code,name:item.name,unit:item.unit||'Nos',qty:Math.max(1,number(stockRow?.suggestedQty)),rate:number(item.rate),supplier:supplierCode,priority:stockRow?.reorderPriority==='Urgent'?'Urgent':'Normal'});
  cartOpen.value = true;
}
function removeOrder(index) { cart.value.splice(index,1); }
async function refreshDraftOrders(created) {
  const previous = [...draftOrders.value];
  const rows = [];
  for (const entry of created || []) {
    try {
      const result = await request('frappe.client.get', { args:{doctype:'Purchase Order',name:entry.name}, csrfToken:session.csrf_token });
      const doc = result.message || {};
      const transitionResult = await fetch('/api/method/frappe.model.workflow.get_transitions',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Frappe-CSRF-Token':session.csrf_token||''},body:new URLSearchParams({doc:JSON.stringify(doc)}).toString()});
      const transitionBody = await transitionResult.json().catch(()=>({}));
      rows.push({...entry,workflow_state:doc.workflow_state||doc.status||'Draft',grand_total:number(doc.grand_total||entry.grand_total),doc,transitions:transitionBody.message||[]});
    } catch (cause) { rows.push({...entry,load_error:cause.message||'Could not load workflow state.',transitions:[]}); }
  }
  draftOrders.value = [...previous.filter(old=>!rows.some(row=>row.name===old.name)),...rows];
}
async function sendDraftForApproval(order) {
  const action = order.transitions.map(row=>row.action).find(value=>/send.*approval|submit.*approval|request.*approval/i.test(String(value))) || order.transitions.map(row=>row.action).find(value=>/approval/i.test(String(value)));
  if (!action) { actionError.value = `No approval transition is available for ${order.name}.`; return; }
  if (!window.confirm(`Run “${action}” for Purchase Order ${order.name}?`)) return;
  actionBusy.value=true; actionError.value='';
  try {
    const response=await fetch('/api/method/frappe.model.workflow.apply_workflow',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Frappe-CSRF-Token':session.csrf_token||''},body:new URLSearchParams({doc:JSON.stringify(order.doc),action}).toString()});
    const body=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(body.exception||body.exc_type||'Could not send Purchase Order for approval.');
    await refreshDraftOrders([{...order,...(body.message||{})}]);
  } catch(cause){actionError.value=cause.message||'Workflow action failed.';}
  finally{actionBusy.value=false;}
}
async function createDraftOrders() {
  if (!cart.value.length || actionBusy.value) return;
  if (cart.value.some(row=>!row.supplier || number(row.qty)<=0)) { actionError.value = 'Every item needs a supplier and a quantity greater than zero.'; return; }
  if (!window.confirm(`Create draft Purchase Orders for ${cart.value.length} item(s)? One draft will be created per supplier.`)) return;
  actionBusy.value = true; actionError.value = ''; actionMessage.value = '';
  try {
    const args = new URLSearchParams({action:'create_purchase_orders',cart_count:String(cart.value.length)});
    cart.value.forEach((row,index)=>{ for (const [key,value] of Object.entries({item:row.item,item_name:row.name,qty:row.qty,rate:row.rate,supplier:row.supplier,priority:row.priority})) args.set(`cart_${index}_${key}`,String(value)); });
    const response = await fetch('/api/method/life_stores_360_live_api',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Frappe-CSRF-Token':session.csrf_token||''},body:args.toString()});
    const body = await response.json();
    if (!response.ok || !body.message?.ok) throw new Error(body.message?.message || body.exception || 'Draft Purchase Order creation failed.');
    const created=body.message.created || [];
    actionMessage.value = (body.message.message || 'Draft Purchase Orders created.')+' '+created.map(row=>row.name).filter(Boolean).join(', ');
    cart.value = []; await refreshDraftOrders(created);
  } catch (cause) { actionError.value = cause.message || 'Draft Purchase Order creation failed.'; }
  finally { actionBusy.value = false; }
}
function downloadRows(rows, filename, type='csv') {
  if (!rows.length) return;
  const keys = Object.keys(rows[0]);
  const esc = value => String(value ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
  if (type === 'html') {
    const content=`<!doctype html><meta charset="utf-8"><title>${esc(filename)}</title><style>body{font:13px Arial;padding:24px}table{border-collapse:collapse;width:100%}th,td{padding:7px;border:1px solid #bbb;text-align:left}th{background:#edf4ee}</style><h1>${esc(filename)}</h1><table><thead><tr>${keys.map(key=>`<th>${esc(key)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${keys.map(key=>`<td>${esc(row[key])}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
    const url=URL.createObjectURL(new Blob([content],{type:'text/html'}));const link=document.createElement('a');link.href=url;link.download=filename.replace(/\\.csv$/i,'.html');link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;
  }
  if (type === 'xls') {
    const content=`<html><meta charset="utf-8"><table><thead><tr>${keys.map(key=>`<th>${esc(key)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${keys.map(key=>`<td>${esc(row[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></html>`;
    const url=URL.createObjectURL(new Blob([content],{type:'application/vnd.ms-excel'}));const link=document.createElement('a');link.href=url;link.download=filename.replace(/\\.csv$/i,'.xls');link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;
  }
  const csv=[keys.join(','),...rows.map(row=>keys.map(key=>{let value=row[key]??'';if(typeof value==='string'&&/^\s*[=+@-]/.test(value))value="'"+value;return `"${String(value).replaceAll('"','""')}"`}).join(','))].join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function clientExportRows() {
  const rows=clientReportRows.value.map(row=>({client:row.clientData.name,client_id:row.client,mobile_last4:String(row.clientData.mob||'').replace(/\\D/g,'').slice(-4),branch:branchName(row.br),category:itemByCode(row.item).cat,treatment:row.expectedTreatmentCategory||row.treatment||'',item:row.itemName||row.item,request:row.req,request_date:row.date,given_date:row.givenDate||'',executed:row.executionEvidence||row.execution_evidence||'No',execution_status:row.executionStatus||row.execution_status||'',requested:row.reqQty??row.qty,approved:row.approvedQty??'',released:row.releasedQty,received:row.recQty,pending:row.pendingQty,missing:row.missingQty,damaged:row.damagedQty,receipt_diff:row.receiptReconciliationDiff,status:row.receiptStatus||row.status}));
  if(clientView.value!=='statement')return rows;
  return [...new Map(rows.map(row=>[row.client_id,row])).values()].flatMap(client=>{const mine=rows.filter(row=>row.client_id===client.client_id);return [{client_statement:`${client.client} · ${client.client_id}`,lines:mine.length,requested:mine.reduce((s,r)=>s+number(r.requested),0),released:mine.reduce((s,r)=>s+number(r.released),0),received:mine.reduce((s,r)=>s+number(r.received),0),pending:mine.reduce((s,r)=>s+number(r.pending),0)},...mine];});
}
function downloadClient(format) {
  let rows=clientExportRows();
  if(format==='pdf'){window.print();return;}
  if(format==='summary')rows=[...new Map(rows.map(row=>[row.client_id,row])).values()].map(client=>{const mine=rows.filter(row=>row.client_id===client.client_id);return {client:client.client,client_id:client.client_id,lines:mine.length,requested:mine.reduce((s,r)=>s+number(r.requested),0),released:mine.reduce((s,r)=>s+number(r.released),0),received:mine.reduce((s,r)=>s+number(r.received),0),pending:mine.reduce((s,r)=>s+number(r.pending),0)};});
  downloadRows(rows,`client-stock-${from.value}-${to.value}.csv`,format==='xls'?'xls':format==='html'?'html':'csv');
}
function exportCsv() {
  if(tab.value==='client'){downloadRows(clientExportRows(),`client-stock-${from.value}-${to.value}.csv`);return;}
  const rows = tab.value === 'stock' ? (movementType.value ? reportMovements.value.map(row=>({movement:row.movement,date:row.date,reference:row.ref||row.inv,item:row.item,item_name:row.itemName,location:row.location,quantity:row.qty,value:row.value,vendor:row.vendor||''})) : stockRows.value.map(row=>({item:row.code,name:row.name,category:row.cat,type:row.type,quantity:row.onHand,unit:row.unit,reorder_level:row.rl})))
    : tab.value === 'item' ? itemMovements.value.map(row=>({movement:row.movement,date:row.date,reference:row.ref||row.inv,item:row.item,location:row.branch||row.loc||row.warehouse,quantity:row.qty,rate:row.rate,value:row.val,vendor:row.vendor||''}))
    : tab.value === 'vendor' ? vendorPurchases.value.map(row=>({receipt:row.inv,date:row.date,item:row.item_name||row.item,quantity:row.qty,rate:row.rate,value:row.val,warehouse:row.warehouse}))
    : requests.value.map(row=>({request:row.req,date:row.date,branch:row.br,item:row.item,item_name:row.itemName,client:row.client,requested:row.reqQty??row.qty,approved:row.approvedQty,released:row.releasedQty,received:row.recQty,pending:row.pendingQty,missing:row.missingQty,damaged:row.damagedQty,executed:row.executionEvidence||row.execution_evidence,status:row.receiptStatus||row.status}));
  if (!rows.length) return;
  const keys = Object.keys(rows[0]);
  const csv = [keys.join(','), ...rows.map(row=>keys.map(key=>{let value=row[key]??'';if(typeof value==='string'&&/^\s*[=+@-]/.test(value))value="'"+value;return `"${String(value).replaceAll('"','""')}"`}).join(','))].join('\r\n');
  const url = URL.createObjectURL(new Blob([csv], {type:'text/csv;charset=utf-8'}));
  const link = document.createElement('a'); link.href = url; link.download = `stores-360-${tab.value}-${from.value}-${to.value}.csv`; link.click(); setTimeout(()=>URL.revokeObjectURL(url),1000);
}
onMounted(load);
onBeforeUnmount(()=>{controller?.abort();detailController?.abort();});
</script>

