        <template v-if="activeReport==='purchase-register'"><div class="stores-table-scroll"><table><thead><tr><th>Purchase receipt</th><th>Purchase order</th><th>Date</th><th>Supplier</th><th>Item</th><th>Warehouse</th><th>Qty</th><th>Rate</th><th>Value</th></tr></thead><tbody><tr v-for="(row,index) in reportMovements" :key="`${row.ref}-${row.item}-${index}`"><td>{{ row.ref||row.inv }}</td><td>{{ row.po||'—' }}</td><td>{{ dateText(row.date) }}</td><td>{{ row.vendor_name||row.vendor||'—' }}</td><td>{{ row.itemName }}</td><td>{{ branchName(row.warehouse||row.location) }}</td><td>{{ qty(row.qty) }}</td><td>{{ qty(row.rate) }}</td><td>₹{{ qty(row.value) }}</td></tr></tbody></table></div></template>
