        <template v-if="activeReport==='status-summary'"><div class="stores-table-scroll"><table><thead><tr><th>Branch</th><th>Requests</th><th>Released</th><th>Received</th><th>Missing</th><th>Damaged</th><th>Pending</th><th>Mismatch lines</th></tr></thead><tbody><tr v-for="row in branches.map(item=>{const mine=statusRows.filter(request=>request.br===item.code);return {item,mine}})" :key="row.item.code"><td>{{ row.item.name }}</td><td>{{ row.mine.length }}</td><td>{{ qty(row.mine.reduce((s,r)=>s+number(r.releasedQty),0)) }}</td><td>{{ qty(row.mine.reduce((s,r)=>s+number(r.recQty),0)) }}</td><td>{{ qty(row.mine.reduce((s,r)=>s+number(r.missingQty),0)) }}</td><td>{{ qty(row.mine.reduce((s,r)=>s+number(r.damagedQty),0)) }}</td><td>{{ qty(row.mine.reduce((s,r)=>s+number(r.pendingReceiptQty),0)) }}</td><td>{{ row.mine.filter(r=>number(r.receiptReconciliationDiff)>0).length }}</td></tr></tbody></table></div></template>
