      <section v-else-if="tab==='requests'" class="stores-table-card"><div class="stores-module-head"><div><h2>Indent 360</h2><p>Material requests, approvals, releases and receipt reconciliation.</p></div><span>{{ statusRows.length }} request lines</span></div><div class="stores-ledger-filters"><label>Workflow / receipt status<select v-model="requestState"><option value="">All statuses</option><option v-for="name in requestStates" :key="name">{{ name }}</option></select></label><label>Issued from<select v-model="requestSource"><option value="">All sources</option><option value="HO">Head Office</option><option value="BR">Branch transfer</option></select></label><label>Pending age<select v-model="clientAge"><option value="">Any</option><option value="15">Over 15 days</option><option value="30">Over 30 days</option><option value="60">Over 60 days</option></select></label></div><div class="stores-table-scroll"><table><thead><tr><th>Request</th><th>Date / required by</th><th>Branch</th><th>Item</th><th>Client / purpose</th><th>Requested</th><th>Approved</th><th>Released</th><th>Received</th><th>Pending receipt</th><th>Missing</th><th>Damaged</th><th>Diff</th><th>Status</th></tr></thead><tbody><tr v-for="(row,index) in statusRows" :key="`${row.req}-${row.item}-${index}`"><td><strong>{{ row.req }}</strong><small>{{ row.requestBy || row.reqBy || '—' }} · {{ row.priority || 'Normal' }}</small></td><td>{{ dateText(row.date) }}<small>Need {{ dateText(row.needDate) }}</small></td><td>{{ branchName(row.br) }}</td><td><button class="stores-link" @click="openItem(row.item)">{{ row.itemName || itemByCode(row.item).name }}</button><small>{{ row.item }}</small></td><td>{{ row.client || row.expectedClient || row.requestType || row.therapy || '—' }}</td><td>{{ qty(row.reqQty ?? row.qty) }} {{ row.unit }}</td><td>{{ row.approvedQty == null ? '—' : qty(row.approvedQty) }}</td><td>{{ qty(row.releasedQty) }}</td><td>{{ qty(row.recQty) }}</td><td>{{ qty(row.pendingReceiptQty) }}</td><td>{{ row.missingQty == null ? '—' : qty(row.missingQty) }}</td><td>{{ row.damagedQty == null ? '—' : qty(row.damagedQty) }}</td><td>{{ row.receiptReconciliationDiff == null ? '—' : qty(row.receiptReconciliationDiff) }}</td><td><span class="stores-status-badge">{{ row.receiptStatus || row.status || '—' }}</span><small v-if="row.stockEntry">{{ row.stockEntry }}</small></td></tr><tr v-if="!statusRows.length"><td colspan="14" class="stores-empty">No requests match the selected filters.</td></tr></tbody></table></div></section>
      <section v-else-if="tab==='client'" class="stores-table-card"><div class="stores-module-head"><div><h2>Client – Stock Report</h2><p>Stock given, treatment execution evidence, pending age and downloadable client statements.</p></div><select v-model="selectedClient"><option value="">All clients in this report</option><option v-for="client in clientOptions" :key="client.id" :value="client.id">{{ client.name }} · {{ client.id }}</option></select></div><div class="stores-ledger-filters"><label>Request from<input v-model="clientFrom" type="date"></label><label>Request to<input v-model="clientTo" type="date"></label></div><form class="stores-client-search" @submit.prevent="searchClients"><label>Find a client by name, ID or mobile<input v-model="query" type="search" placeholder="Client name, ID, or mobile"></label><button class="stores-primary" :disabled="clientLookupBusy">{{ clientLookupBusy?'Searching…':'Search clients' }}</button><span v-if="clientLookupError" role="status">{{ clientLookupError }}</span></form><div v-if="clientMatches.length" class="stores-client-matches"><button v-for="client in clientMatches" :key="client.id" @click="selectedClient=client.id">{{ client.name }} <small>{{ client.id }} · {{ client.mob ? '••••'+String(client.mob).replace(/\D/g,'').slice(-4) : 'Mobile unavailable' }} · {{ branchName(client.br) }}</small></button></div><div class="stores-client-controls"><label>View<select v-model="clientView"><option value="register">Register</option><option value="statement">Client Statement</option></select></label><label>Treatment<select v-model="clientTreatment"><option value="">All treatments</option><option v-for="value in treatments" :key="value">{{ value }}</option></select></label><label>Requested by<select v-model="clientRequester"><option value="">All requesters</option><option v-for="value in clientRequesters" :key="value">{{ value }}</option></select></label><label><input v-model="clientPendingOnly" type="checkbox">Pending execution / stock only</label><label>Executed<select v-model="clientExecutionFilter"><option value="">Yes + No</option><option value="Yes">Executed</option><option value="No">Pending execution</option></select></label><label>Pending age<select v-model="clientAge"><option value="">Any age</option><option value="15">Over 15 days</option><option value="30">Over 30 days</option><option value="60">Over 60 days</option></select></label><button @click="downloadClient('pdf')">PDF / Print</button><button @click="downloadClient('xls')">Excel</button><button @click="downloadClient('csv')">CSV</button><button @click="downloadClient('summary')">Summary</button><button @click="downloadClient('html')">HTML</button></div><div v-if="selectedClient" class="stores-client-summary"><span>Client stock statement · {{ clientById(selectedClient).name }} · {{ selectedClient }}</span><span>{{ clientTotals.lines }} lines</span><span>Requested {{ qty(clientTotals.requested) }}</span><span>Released {{ qty(clientTotals.released) }}</span><span>Received {{ qty(clientTotals.received) }}</span><span>Pending {{ qty(clientTotals.pending) }}</span></div><div v-if="clientView==='statement'" class="stores-table-scroll"><table><thead><tr><th>Client</th><th>Client ID</th><th>Branch</th><th>Lines</th><th>Requested</th><th>Released</th><th>Received</th><th>Pending</th></tr></thead><tbody><tr v-for="row in [...new Map(clientReportRows.map(item=>[item.client,item])).values()].map(client=>{const mine=clientReportRows.filter(item=>item.client===client.client);return {client,mine}})" :key="row.client.client"><td>{{ row.client.clientData.name }}</td><td>{{ row.client.client }}</td><td>{{ branchName(row.client.br) }}</td><td>{{ row.mine.length }}</td><td>{{ qty(row.mine.reduce((sum,item)=>sum+number(item.reqQty??item.qty),0)) }}</td><td>{{ qty(row.mine.reduce((sum,item)=>sum+number(item.releasedQty),0)) }}</td><td>{{ qty(row.mine.reduce((sum,item)=>sum+number(item.recQty),0)) }}</td><td>{{ qty(row.mine.reduce((sum,item)=>sum+number(item.pendingQty),0)) }}</td></tr></tbody></table></div><div v-else class="stores-table-scroll"><table><thead><tr><th>Client</th><th>Branch</th><th>Stock item</th><th>Request date</th><th>Given date</th><th>Request by</th><th>Requested</th><th>Released</th><th>Received</th><th>Pending</th><th>Execution</th><th>Age</th></tr></thead><tbody><tr v-for="(row,index) in clientReportRows" :key="`${row.req}-${row.item}-${index}`"><td><strong>{{ row.clientData.name }}</strong><small>{{ row.client }} · {{ row.clientData.mob ? '••••'+String(row.clientData.mob).replace(/\D/g,'').slice(-4) : 'Mobile unavailable' }}</small></td><td>{{ branchName(row.br) }}</td><td><button class="stores-link" @click="openItem(row.item)">{{ row.itemName || row.item }}</button></td><td>{{ dateText(row.date) }}</td><td>{{ dateText(row.givenDate) }}</td><td>{{ row.requestBy || '—' }}</td><td>{{ qty(row.reqQty ?? row.qty) }} {{ row.unit }}</td><td>{{ qty(row.releasedQty) }}</td><td>{{ qty(row.recQty) }}</td><td>{{ qty(row.pendingQty) }}</td><td>{{ row.executionEvidence || row.execution_evidence || 'No' }}<small>{{ row.executionStatus || row.execution_status || '—' }}</small></td><td>{{ ageDays(row.givenDate||row.date) }} days</td></tr><tr v-if="!clientReportRows.length"><td colspan="12" class="stores-empty">No client stock lines match these filters.</td></tr></tbody></table></div></section>
      <section v-else-if="tab==='status'" class="stores-table-card"><div class="stores-module-head"><div><h2>Stock Request Status Report</h2><p>Approval, release, receipt balance and reconciliation evidence.</p></div><span>{{ reportStatusRows.filter(row=>row.receiptStatus==='Received').length }} received</span></div><div class="stores-ledger-filters"><label>Workflow / receipt status<select v-model="requestState"><option value="">All statuses</option><option v-for="name in requestStates" :key="name">{{ name }}</option></select></label><label>Given from<select v-model="requestSource"><option value="">All locations</option><option value="HO">HO only</option><option value="BR">Branch transfer</option></select></label><label>Receipt difference<select v-model="diffFilter"><option value="">All</option><option value="tallied">Tallied</option><option value="mismatch">Mismatch only</option></select></label><label>Request from<input v-model="statusFrom" type="date"></label><label>Request to<input v-model="statusTo" type="date"></label><label>Requested by<select v-model="statusRequester"><option value="">All requesters</option><option v-for="value in statusRequesters" :key="value">{{ value }}</option></select></label><label>Stock item<input v-model="statusItem" type="search" placeholder="Item name or code"></label><label>Pending age<select v-model="clientAge"><option value="">Any age</option><option value="15">Over 15 days</option><option value="30">Over 30 days</option><option value="60">Over 60 days</option></select></label><button @click="downloadRows(reportStatusRows.map(row=>({request:row.req,branch:branchName(row.br),date:row.date,request_by:row.requestBy,item:row.itemName,requested:row.reqQty??row.qty,approved:row.approvedQty,released:row.releasedQty,received:row.recQty,missing:row.missingQty,damaged:row.damagedQty,difference:row.receiptReconciliationDiff,execution:row.executionEvidence,status:row.receiptStatus||row.status})),`status-report-${from}-${to}.csv`)">Download CSV</button></div><div class="stores-table-scroll"><table><thead><tr><th>Request / branch</th><th>Request by</th><th>Item / type</th><th>Requested</th><th>Approved</th><th>Released</th><th>Received</th><th>Missing</th><th>Damaged</th><th>Diff</th><th>Execution</th><th>Workflow status</th></tr></thead><tbody><tr v-for="(row,index) in reportStatusRows" :key="`${row.req}-${row.item}-${index}`"><td><strong>{{ row.req }}</strong><small>{{ branchName(row.br) }} · {{ dateText(row.date) }}</small></td><td>{{ row.requestBy || '—' }}<small>{{ row.priority || 'Normal' }}</small></td><td>{{ row.itemName || row.item }}<small>{{ row.stockType || row.requestType || '—' }}</small></td><td>{{ qty(row.reqQty ?? row.qty) }}</td><td>{{ row.approvedQty == null ? '—' : qty(row.approvedQty) }}</td><td>{{ qty(row.releasedQty) }}</td><td>{{ qty(row.recQty) }}</td><td>{{ row.missingQty == null ? '—' : qty(row.missingQty) }}</td><td>{{ row.damagedQty == null ? '—' : qty(row.damagedQty) }}</td><td>{{ row.receiptReconciliationDiff == null ? '—' : qty(row.receiptReconciliationDiff) }}</td><td>{{ row.executionEvidence || '—' }}</td><td><span class="stores-status-badge">{{ row.status }}</span><small>{{ row.receiptStatus }}</small></td></tr><tr v-if="!reportStatusRows.length"><td colspan="12" class="stores-empty">No requests match these filters.</td></tr></tbody></table></div><p class="stores-footnote">Receipt discrepancies are from LIFE Stock Receipt Adjustment evidence. Execution status follows the linked therapy session; numeric consumed quantity is not inferred.</p></section>
      <section v-else-if="tab==='item'" class="stores-table-card"><div class="stores-module-head"><div><h2>Item 360</h2><p>Item purchase, dispatch, return, consumption and adjustment history.</p></div><select v-model="selectedItem" @change="openItem(selectedItem)"><option value="">Choose an item</option><option v-for="row in data.items" :key="row.code" :value="row.code">{{ row.name }} · {{ row.code }}</option></select></div><template v-if="selectedItem"><div class="stores-detail-kpis"><article><span>Current HO balance</span><strong>{{ qty(data.ho_stock?.[selectedItem]) }} {{ item.unit }}</strong></article><article><span>Branch balance</span><strong>{{ qty(Object.values(data.branch_stock?.[selectedItem]||{}).reduce((s,v)=>s+number(v),0)) }} {{ item.unit }}</strong></article><article><span>Reorder level</span><strong>{{ qty(item.rl) }} {{ item.unit }}</strong></article><article><span>Supplier links</span><strong>{{ (data.item_vendors?.[selectedItem]||[]).length }}</strong></article></div><p class="stores-item-vendors"><strong>Linked suppliers:</strong> <button v-for="code in data.item_vendors?.[selectedItem]||[]" :key="code" class="stores-link" @click="openVendor(code)">{{ vendors.find(row=>row.code===code)?.name || code }}</button><span v-if="!(data.item_vendors?.[selectedItem]||[]).length">No linked supplier records.</span></p><h3>Movement summary · vendor supply to present balance</h3><div class="stores-table-scroll"><table><thead><tr><th>Period</th><th>Purchased qty</th><th>Purchase worth</th><th>Sent qty</th><th>Sent worth</th><th>Return to HO</th><th>Consumed</th><th>Damage / adjustment</th></tr></thead><tbody><tr v-for="row in itemSummaryRows" :key="row.period"><td>{{ row.period }}</td><td>{{ qty(row.purchased) }}</td><td>₹{{ qty(row.purchaseWorth) }}</td><td>{{ qty(row.sent) }}</td><td>₹{{ qty(row.sentWorth) }}</td><td>{{ qty(row.returned) }}</td><td>{{ qty(row.consumed) }}</td><td>{{ qty(row.adjusted) }}</td></tr></tbody></table></div><h3>Stock in hand · HO and branches</h3><div class="stores-table-scroll"><table><thead><tr><th>Location</th><th>Quantity</th><th>Available share</th></tr></thead><tbody><tr v-for="row in itemBranchRows" :key="row.code"><td>{{ row.name }}</td><td>{{ qty(row.qty) }} {{ item.unit }}</td><td>{{ qty(row.qty/Math.max(1,itemBranchRows.reduce((sum,entry)=>sum+entry.qty,0))*100) }}%</td></tr></tbody></table></div><h3>Vendors supplying this item</h3><div class="stores-table-scroll"><table><thead><tr><th>Vendor</th><th>Phone / terms</th><th>Since</th><th>Lifetime qty</th><th>Receipt value</th><th>Last rate</th><th>Last receipt</th><th>Total due</th></tr></thead><tbody><tr v-for="row in itemVendorRows" :key="row.code"><td><button class="stores-link" @click="openVendor(row.code)">{{ row.name }}</button></td><td>{{ row.phone||'—' }} · {{ row.terms||'Terms unavailable' }}</td><td>{{ dateText(row.since) }}</td><td>{{ qty(row.qty) }}</td><td>₹{{ qty(row.value) }}</td><td>₹{{ qty(row.lastRate) }}</td><td>{{ dateText(row.lastDate) }}</td><td>₹{{ qty(row.due) }}</td></tr><tr v-if="!itemVendorRows.length"><td colspan="8" class="stores-empty">No vendor receipt records found.</td></tr></tbody></table></div><h3>Product complaints</h3><div class="stores-empty">Complaint records are not returned by the current live ERP API.</div><p v-if="detailLoading" role="status">Loading item movement history…</p><p v-if="actionError" class="stores-error" role="alert">{{ actionError }}</p><div class="stores-table-scroll"><table><thead><tr><th>Movement</th><th>Date</th><th>Reference</th><th>Location</th><th>Quantity</th><th>Rate</th><th>Value</th><th>Supplier / details</th></tr></thead><tbody><tr v-for="(row,index) in itemMovements" :key="`${row.movement}-${row.ref||row.inv}-${index}`"><td>{{ row.movement }}</td><td>{{ dateText(row.date) }}</td><td>{{ row.ref || row.inv || row.po || '—' }}</td><td>{{ branchName(row.branch || row.loc || row.warehouse) }}</td><td>{{ qty(row.qty) }} {{ item.unit }}</td><td>{{ row.rate ? '₹'+qty(row.rate) : '—' }}</td><td>{{ row.val ? '₹'+qty(row.val) : '—' }}</td><td>{{ row.vendor_name || row.vendor || row.reason || row.client || '—' }}</td></tr><tr v-if="!detailLoading&&!itemMovements.length"><td colspan="8" class="stores-empty">No item history returned.</td></tr></tbody></table></div><button @click="addToOrder(item)">Add item to Next Order List</button></template><p v-else class="stores-empty">Select a stock item to see its history.</p></section>
      <section v-else class="stores-vendor-layout"><aside class="stores-vendor-list"><h2>Vendor 360</h2><input v-model="query" type="search" placeholder="Search suppliers"><button v-for="row in vendors.filter(v=>qmatch([v.code,v.name,v.phone]))" :key="row.code" :class="{active:selectedVendor===row.code}" @click="openVendor(row.code)">{{ row.name }}<small>{{ row.code }}</small></button></aside><section class="stores-table-card"><template v-if="vendor"><div class="stores-module-head"><div><h2>{{ vendor.name }}</h2><p>{{ vendor.code }} · {{ vendor.level || vendor.supplierType || 'Supplier' }} · {{ vendor.phone || 'No phone' }}</p><small>{{ vendor.email }} · {{ vendor.terms || 'Payment terms unavailable' }} · Since {{ dateText(vendor.since) }} · {{ vendor.city||'Location unavailable' }} · {{ vendor.branch||'No branch' }}</small><small>Area manager: {{ vendor.areaManager||'—' }} · Relationship manager: {{ vendor.rm||'—' }} · {{ vendor.rmPhone||'' }} · Materials: {{ vendor.materials||'Not specified' }}</small></div><span>{{ vendor.blocked ? 'On hold / disabled' : 'Active' }}</span></div><div class="stores-detail-kpis"><article><span>Period billed</span><strong>₹{{ qty(vendor.billed) }}</strong></article><article><span>Period paid</span><strong>₹{{ qty(vendor.paid) }}</strong></article><article><span>Period due</span><strong>₹{{ qty(vendor.due) }}</strong></article><article><span>Invoices</span><strong>{{ vendor.invoiceCount || 0 }}</strong></article></div><div class="stores-detail-kpis"><article><span>Lifetime billed</span><strong>₹{{ qty(vendor.lifetimeBilled) }}</strong></article><article><span>Lifetime paid</span><strong>₹{{ qty(vendor.lifetimePaid) }}</strong></article><article><span>Lifetime due</span><strong>₹{{ qty(vendor.lifetimeDue) }}</strong></article><article><span>Open lifetime invoices</span><strong>{{ vendor.lifetimeOpenInvoiceCount||0 }}</strong></article></div><h3>Supplied stock items · live balance</h3><div class="stores-table-scroll"><table><thead><tr><th>Item</th><th>Lifetime receipt qty</th><th>Live stock</th><th>Receipts in period</th></tr></thead><tbody><tr v-for="row in vendorItems" :key="row.item.code"><td><button class="stores-link" @click="openItem(row.item.code)">{{ row.item.name }}</button><small>{{ row.item.code }} · {{ row.item.cat }} · {{ row.item.type }}</small></td><td>{{ qty(row.qty) }}</td><td>{{ qty(row.stock) }} {{ row.item.unit }}</td><td>{{ row.receipts.length }}</td></tr><tr v-if="!vendorItems.length"><td colspan="4" class="stores-empty">No supplied items matched.</td></tr></tbody></table></div><h3>Where this vendor’s material goes · branch ranking</h3><div class="stores-table-scroll"><table><thead><tr><th>Rank / branch</th><th>City</th><th>Qty received</th><th>Worth</th><th>In hand now</th></tr></thead><tbody><tr v-for="(row,index) in vendorReach" :key="row.code"><td>{{ index+1 }} · {{ row.name }}</td><td>{{ row.city||'—' }}</td><td>{{ qty(row.qty) }}</td><td>₹{{ qty(row.value) }}</td><td>{{ qty(row.inHand) }}</td></tr><tr v-if="!vendorReach.length"><td colspan="5" class="stores-empty">No branch dispatch data for this vendor’s supplied items.</td></tr></tbody></table></div><h3>Complaints against this vendor</h3><div class="stores-empty">Vendor complaint records are not returned by the current live ERP API.</div><h3>Purchase Receipt history</h3><div class="stores-table-scroll"><table><thead><tr><th>Receipt</th><th>Purchase Order</th><th>Date</th><th>Item</th><th>Qty</th><th>Rate</th><th>Value</th><th>Warehouse</th></tr></thead><tbody><tr v-for="(row,index) in vendorPurchases" :key="`${row.inv}-${row.item}-${index}`"><td>{{ row.inv }}</td><td>{{ row.po || '—' }}</td><td>{{ dateText(row.date) }}</td><td><button class="stores-link" @click="openItem(row.item)">{{ row.item_name || itemByCode(row.item).name }}</button></td><td>{{ qty(row.qty) }}</td><td>{{ row.rate ? '₹'+qty(row.rate) : '—' }}</td><td>{{ row.val ? '₹'+qty(row.val) : '—' }}</td><td>{{ branchName(row.warehouse) }}</td></tr><tr v-if="!vendorPurchases.length"><td colspan="8" class="stores-empty">No purchase receipts for this vendor in the selected period.</td></tr></tbody></table></div><h3>Submitted Purchase Invoice ledger</h3><div class="stores-table-scroll"><table><thead><tr><th>Invoice</th><th>Date</th><th>Due date</th><th>Invoice total</th><th>Paid</th><th>Outstanding</th><th>Status</th></tr></thead><tbody><tr v-for="row in vendorInvoices" :key="row.inv"><td>{{ row.inv }}</td><td>{{ dateText(row.date) }}</td><td>{{ dateText(row.due_date) }}</td><td>₹{{ qty(row.grand_total) }}</td><td>₹{{ qty(row.paid) }}</td><td>₹{{ qty(row.due) }}</td><td>{{ row.status }}</td></tr><tr v-if="!vendorInvoices.length"><td colspan="7" class="stores-empty">No submitted purchase invoices for this vendor in the selected period.</td></tr></tbody></table></div><p>Lifetime billed ₹{{ qty(vendor.lifetimeBilled) }} · Paid ₹{{ qty(vendor.lifetimePaid) }} · Due ₹{{ qty(vendor.lifetimeDue) }} · Open invoices {{ vendor.lifetimeOpenInvoiceCount || 0 }}. Supplier complaint data is not returned by the live API.</p></template><p v-else class="stores-empty">Choose a supplier to open Vendor 360.</p></section></section>
      <p v-if="actionMessage" class="stores-success" role="status">Draft Purchase Orders created: {{ actionMessage }}</p>
      <p class="stores-footnote">Live ERP data only. Execution quantity is not inferred; receipt discrepancy values use submitted receipt-adjustment records.</p>
    </template>
    <div v-if="cartOpen" class="stores-cart-backdrop" @click.self="cartOpen=false"><section class="stores-cart" role="dialog" aria-modal="true" aria-label="Next Order List"><header><div><h2>Next Order List</h2><p>Creates one draft Purchase Order per supplier. Drafts are not submitted automatically.</p></div><button @click="cartOpen=false">Close</button></header><p v-if="actionError" class="stores-error" role="alert">{{ actionError }}</p><div v-if="draftOrders.length" class="stores-drafts"><h3>Purchase Order approval status</h3><article v-for="order in draftOrders" :key="order.name"><div><strong>{{ order.name }}</strong><small>{{ order.supplier }} · {{ order.item_count }} item(s) · ₹{{ qty(order.grand_total) }}</small></div><span class="stores-status-badge">{{ order.workflow_state || order.status || 'Draft' }}</span><button v-if="order.transitions?.length" :disabled="actionBusy" @click="sendDraftForApproval(order)">Send for approval</button><small v-if="order.load_error" class="stores-error">{{ order.load_error }}</small></article></div><div v-if="!cart.length" class="stores-empty">{{ draftOrders.length?'No more items parked.':'The order list is empty.' }}</div><div v-for="(row,index) in cart" :key="row.item" class="stores-cart-row"><strong>{{ row.name }}</strong><small>{{ row.item }} · {{ row.unit }} · {{ row.priority }}</small><label>Quantity<input v-model.number="row.qty" type="number" min="0.01" step="0.01"></label><label>Supplier<select v-model="row.supplier"><option value="">Choose supplier</option><option v-for="code in suppliersForItem(row.item)" :key="code" :value="code">{{ vendors.find(v=>v.code===code)?.name || code }}</option></select></label><label>Rate<input v-model.number="row.rate" type="number" min="0" step="0.01"></label><button @click="removeOrder(index)">Remove</button></div><footer><strong>Estimated value ₹{{ qty(orderValue) }}</strong><button :disabled="actionBusy||!cart.length" class="stores-primary" @click="createDraftOrders">{{ actionBusy?'Creating draft…':'Confirm & create draft PO' }}</button></footer></section></div>
  </main>
